    fun byId(id: String) = garments.first { it.id == id }

    fun addImported(garment: Garment) {
        importedGarments.removeAll { it.id == garment.id || (it.name.equals(garment.name, true) && it.subtitle == garment.subtitle) }
        importedGarments += garment
    }

    fun forGender(gender: String?): List<Garment> =
        allGarments.filter { it.audience.matchesGenderLabel(gender) }
}
